1	export type Item = {
2	  type: string;
3	  material: string;
4	  enchantment: number;
5	  cursed: boolean;
6	};
7	
8	export type Step = {
9	  op: string;
10	  items: Item[];
11	};
12	
13	export type Scenario = {
14	  customer: { yearsWithMHPCO: number };
15	  steps: Step[];
16	};
17	
18	export type StepResult = {
19	  premium: number;
20	};
21	
22	export type ScenarioResult = {
23	  results: StepResult[];
24	};
25	
26	const BASE_PRICES: Record<string, number> = {
27	  sword: 100,
28	  amulet: 60,
29	  staff: 80,
30	  potion: 40,
31	  rune: 25,
32	  moonstone: 25,
33	};
34	
35	// Expressed as integer percent rather than a 1.1 factor: floating-point
36	// multiplication by 1.1 loses exactness (100 * 1.1 === 115.00000000000001),
37	// while scaling by 110 and dividing by 100 stays exact for these prices.
38	const FIRST_CONTRACT_PERCENT = 110;
39	const WHOLE_PERCENT = 100;
40	const CONTRACT_FEE = 5;
41	
42	const BLOCK_SIZE = 3;
43	const BLOCK_PRICE = 60;
44	
45	const COMPONENT_TYPES = ["rune", "moonstone"];
46	
47	const CURSED_PERCENT = 150;
48	
49	const HIGH_ENCHANTMENT_LEVEL = 5;
50	const HIGH_ENCHANTMENT_PERCENT = 130;
51	
52	const applyPercent = (amount: number, percent: number): number =>
53	  (amount * percent) / WHOLE_PERCENT;
54	
55	const tablePriceOf = (item: Item): number => BASE_PRICES[item.type];
56	
57	// Risk surcharges stack multiplicatively: each one that applies scales the
58	// running price, so a cursed item is 150 % of the table price.
59	const RISK_SURCHARGES: { applies: (item: Item) => boolean; percent: number }[] =
60	  [
61	    { applies: (item) => item.cursed, percent: CURSED_PERCENT },
62	    {
63	      applies: (item) => item.enchantment >= HIGH_ENCHANTMENT_LEVEL,
64	      percent: HIGH_ENCHANTMENT_PERCENT,
65	    },
66	  ];
67	
68	const riskAdjustedPriceOf = (item: Item): number =>
69	  RISK_SURCHARGES.filter((surcharge) => surcharge.applies(item)).reduce(
70	    (price, surcharge) => applyPercent(price, surcharge.percent),
71	    tablePriceOf(item),
72	  );
73	
74	const isComponent = (item: Item): boolean =>
75	  COMPONENT_TYPES.includes(item.type);
76	
77	const allAlike = (items: Item[]): boolean =>
78	  items.every((item) => item.type === items[0].type);
79	
80	// Only alike components combine into blocks — main items (swords, staves,
81	// potions, amulets) are always priced individually, however many there are.
82	const formsBuildingBlocks = (items: Item[]): boolean =>
83	  items.every(isComponent) && allAlike(items);
84	
85	const sumOfItemPrices = (items: Item[]): number =>
86	  items.reduce((total, item) => total + riskAdjustedPriceOf(item), 0);
87	
88	// Every group of BLOCK_SIZE alike components is priced as one discounted
89	// building block; leftovers keep their individual price.
90	const buildingBlockPriceOf = (items: Item[]): number => {
91	  const blocks = Math.floor(items.length / BLOCK_SIZE);
92	  const itemsInBlocks = blocks * BLOCK_SIZE;
93	  const leftovers = items.slice(itemsInBlocks);
94	  return blocks * BLOCK_PRICE + sumOfItemPrices(leftovers);
95	};
96	
97	const itemsPriceOf = (items: Item[]): number =>
98	  formsBuildingBlocks(items)
99	    ? buildingBlockPriceOf(items)
100	    : sumOfItemPrices(items);
101	
102	// Premiums are always rounded up — rounding in MHPCO's favour, per spec.
103	const premiumFor = (itemsPrice: number): number =>
104	  Math.ceil(applyPercent(itemsPrice, FIRST_CONTRACT_PERCENT) + CONTRACT_FEE);
105	
106	const quote = (step: Step): StepResult => ({
107	  premium: premiumFor(itemsPriceOf(step.items)),
108	});
109	
110	export const run = (scenario: Scenario): ScenarioResult => ({
111	  results: [quote(scenario.steps[0])],
112	});
